  _ = `Sekcja odnośnikowa`,
  _ = `Obraz tytułu/nagłówka`,
  _ = `Nieznany rodzaj sekcji wyprzedaży`,
  _ = `Ta sekcja zawiera tylko obraz. Czy zamiast tego chcesz <1>skonwertować</1> ją do sekcji obrazu tytułu?`,
  _ = `Sekcje obrazów umożliwiają łatwiejsze przetłumaczenie obrazu oraz są szybciej generowane na finalnej stronie wyprzedaży prezentowanej klientom. Obrazy wykorzystywane w nagłówku tytułu nie zaśmiecają również selektora obrazów.`,
  _ = `Podgląd treści udostępnianych w mediach społecznościowych`,
  _ = `Jest to podgląd treści, które pojawią się, gdy wydarzenie zostanie udostępnione lub jego link zostanie umieszczony w mediach społecznościowych.`,
  _ = `Tytuł jest dziedziczony z tytułu wydarzenia.`,
  _ = `Tytuł jest dziedziczony z tytułu strony głównej twórcy.`,
  _ = `Opis jest dziedziczony z podsumowania wydarzenia lub generowany automatycznie z jego opisu.`,
  _ = `Opis jest dziedziczony z opisu strony głównej twórcy.`,
  _ = `Domyślny obraz strony dla mediów społecznościowych (z obrazu okładki): `,
  _ = `Aby spersonalizować treści, użyj sekcji wyprzedaży „Edytor udostępniania w społeczności”.`,
  _ = `Pokazuj przycisk „Udostępnij znajomym” (domyślnie włączone).`,
  _ = `Domyślna treść dla mediów społecznościowych została nadpisana przez sekcję wyprzedaży „Edytor udostępniania w społeczności”.`,
  _ = `Opcjonalne: zamieść linki do mediów społecznościowych powiązanych ze stroną docelową i wydarzeniem. Będą się wyświetlać w standardowy sposób dla wszystkich klientów.`,
