  _ = `Edytuj nieprzetworzone dane`,
  _ = `Zezwala na bezpośrednią edycję listy połączonych produktów dla tej wyprzedaży. Można to wykorzystać do zaimportowania lub wyeksportowania z narzędzi takich jak Excel lub szybkiego dokonania dużych zmian na liście produktów.`,
  _ = `Niestandardowe etykiety`,
  _ = `Umożliwia bezpośrednią edycję listy połączonych produktów dla tej wyprzedaży i zaimportowanie oraz wyeksportowanie samej niestandardowej kolekcji etykiet na produktach wyprzedaży. Jest to głównie używane do importowania zbioru niestandardowych etykiet zarządzanych za pomocą zewnętrznego arkusza, bez modyfikowania innych etykiet na produktach. Dodatkowo podzbiór można zaimportować za pomocą tego okna dialogowego, gdyż nie usunie produktów nieznajdujących się na liście.`,
  _ = `Importuj ze strony dołączenia`,
  _ = `Otwiera okno dialogowe, które umożliwia import wszystkich aplikacji ze strony rejestracji oraz umieszczenie ich na liście połączonych produktów.`,
  _ = `Zsynchronizuj produkty`,
  _ = `Zsynchronizuj etykiety dema`,
  _ = `Przejdzie to przez wszystkie połączone produkty i doda etykiety „HasDemo” do wszystkich aplikacji z demami oraz usunie je ze wszelkich aplikacji, które ich nie mają.`,
  _ = `Zsynchronizuj`,
  _ = `Umożliwi to synchronizację różnych etykiet i innych informacji między połączonymi produktami i innymi źródłami.`,
  _ = `Synchronizowanie etykiet dema`,
  _ = `Edytuj autoetykiety`,
  _ = `Wprowadź nazwę etykiety`,
  _ = `Jest to nazwa etykiety, która zostanie zastosowana do wszelkich połączonych produktów, które pasują do powiązanego filtra.`,
  _ = `Edytuj filtr produktów (filtry: %1$s)`,
  _ = `Edytuj filtr produktów (filtry: %1$s; odfiltrowano: %2$s)`,
  _ = `Umożliwia to przygotowanie filtra, który zostanie zastosowany do wszystkich połączonych produktów przed przydzieleniem ich do sekcji. Możesz użyć tego, by odfiltrować przykładowo wszystkie gry, które nie mają dem lub posiadają etykietę, z której korzystasz.`,
  _ = `Odkrywaj`,
  _ = `Umożliwia korzystanie z narzędzia filtra do sprawdzania obecnie skonfigurowanych połączonych produktów, by zobaczyć, ile z nich spełnia wymagania różnych filtrów lub które mają powiązane z nimi etykiety.`,
  _ = `Edycja zbiorcza`,
  _ = `Umożliwia zbiorcze edytowanie połączonych produktów. Można zamieścić listę produktów, a następnie etykiet do dodania lub usunięcia w formie grupy.`,
  _ = `Autoetykiety`,
  _ = `Umożliwia tworzenie autoetykiet będących filtrem, który zastosuje nazwaną etykietę na każdy pasujący połączony produkt.`,
  _ = `Wyświetlanie produktów`,
