  _ = `Nazwa dołączenia`,
  _ = `Jest to nazwa wyprzedaży, do której odwołuje się strona dołączenia, by była w stanie określić, z której wyprzedaży zaimportować dane.`,
  _ = `Prefiks etykiety`,
  _ = `Prefiks do dołączenia do etykiet dostarczonych przez stronę rejestracji. To umożliwia, by np. „Akcja” określona z poziomu strony rejestracji była oddzielna od „Akcji” na stronie w sklepie.`,
  _ = `Wymagaj dem`,
  _ = `Po zaznaczeniu zezwolenie będą posiadać tylko aplikacje posiadające powiązane demo.`,
  _ = `Wczytywanie aplikacji ze strony rejestracji`,
  _ = `Wczytywanie definicji sklepu, by usunąć aplikacje, którym brakuje stron w sklepie`,
