  _ = `Wczytywanie funkcji aplikacji dla %1$s aplikacji`,
  _ = `Wczytywanie informacji o demach dla %1$s aplikacji`,
  _ = `Wczytywanie informacji o tagach sklepowych dla %1$s aplikacji`,
  _ = `Zezwala na zaawansowaną edycję listy produktów w formacie tekstowym dla tej kapsuły, który umożliwia łatwiejsze zbiorcze importowanie lub eksportowanie z zewnętrznych narzędzi.`,
  _ = `Edytuj produkty sekcji`,
  _ = `Określ produkty i kolejność, w jakiej mają się pojawić.`,
