  _ = `Wybierz wydarzenie zniżkowe.`,
  _ = `Przewiń albo wprowadź nazwę, by rozpocząć wyszukiwanie.`,
  _ = `Wczytaj listę wydarzeń zniżkowych`,
  _ = `Wczytaj szczegóły aplikacji i pakietów wydarzenia zniżkowego`,
  _ = `Nie wybrano wydarzenia zniżkowego.`,
  _ = `Wybrane wydarzenie zniżkowe: %1$s (%2$s)`,
