  _ = `Usuń wszystkie produkty`,
  _ = `Czy na pewno chcesz usunąć wszystkie produkty z tej kapsuły wyprzedaży?`,
  _ = `Dodaj według ID`,
  _ = `Umożliwia wprowadzanie aplikacji, pakietów lub zestawów w partiach, używając przypisanych do nich ID.`,
  _ = `ID aplikacji`,
